<?php
require_once '../includes/auth.php'; require_once '../config/koneksi.php';
$id=(int)($_GET['id']??0);$row=['nama_kelas'=>'','tingkat'=>'VII','wali_kelas'=>'','status'=>'aktif'];$error='';
$st=$conn->prepare('SELECT * FROM kelas WHERE id_kelas=?');$st->bind_param('i',$id);$st->execute();$found=$st->get_result()->fetch_assoc();if(!$found){header('Location: index.php');exit;}$row=$found;$namaLama=$found['nama_kelas'];if($_SERVER['REQUEST_METHOD']==='POST'){$row=array_merge($row,$_POST);$nama=trim($_POST['nama_kelas']??'');$tingkat=$_POST['tingkat']??'';$wali=trim($_POST['wali_kelas']??'');$status=$_POST['status']??'aktif';if($nama===''||!in_array($tingkat,['VII','VIII','IX'],true)||!in_array($status,['aktif','nonaktif'],true)){$error='Lengkapi data dengan benar.';}else{try{$st=$conn->prepare('UPDATE kelas SET nama_kelas=?,tingkat=?,wali_kelas=?,status=? WHERE id_kelas=?');$st->bind_param('ssssi',$nama,$tingkat,$wali,$status,$id);$st->execute();if($nama!==$namaLama){$sync=$conn->prepare('UPDATE siswa SET kelas=? WHERE kelas=?');$sync->bind_param('ss',$nama,$namaLama);$sync->execute();}header('Location: index.php?success=edit');exit;}catch(Throwable $e){$error='Nama kelas sudah digunakan atau data gagal diperbarui.';}}}
$page_title='Edit Kelas';$active='kelas';$prefix='../';include '../includes/header.php';?>
<div class="page-heading"><div><h1>Edit Kelas</h1><p>Perbarui nama kelas, tingkat, atau wali kelas.</p></div><a href="index.php" class="btn btn-light border">Kembali</a></div><div class="panel"><div class="panel-body"><?php if($error):?><div class="alert alert-danger"><?= e($error) ?></div><?php endif;?><form method="post"><div class="row g-3"><div class="col-md-6"><label class="form-label">Nama Kelas *</label><input name="nama_kelas" class="form-control" required value="<?= e($row['nama_kelas']) ?>"></div><div class="col-md-6"><label class="form-label">Tingkat *</label><select name="tingkat" class="form-select"><?php foreach(['VII','VIII','IX'] as $t):?><option value="<?= $t ?>" <?= $row['tingkat']===$t?'selected':'' ?>>Kelas <?= $t ?></option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label">Wali Kelas</label><input name="wali_kelas" class="form-control" value="<?= e($row['wali_kelas']??'') ?>"></div><div class="col-md-6"><label class="form-label">Status</label><select name="status" class="form-select"><option value="aktif" <?= $row['status']==='aktif'?'selected':'' ?>>Aktif</option><option value="nonaktif" <?= $row['status']==='nonaktif'?'selected':'' ?>>Nonaktif</option></select></div></div><div class="d-flex gap-2 mt-4"><button class="btn btn-primary">Simpan Perubahan</button><a href="index.php" class="btn btn-light border">Batal</a></div></form></div></div><?php include '../includes/footer.php';?>